/* Engineering Studio: browser-local workspace, deterministic calculations. */
const baseRender=render;let viewMode='solid',phase=45,playback=false,raf=0,lastFrame=0,sketchTool='rect',sketchStart=null;
tabs.splice(2,0,['sketch','Sketch']);tabs.push(['manufacturing','Build plan']);
const icon={design:'◈',assembly:'⬡',sketch:'⌑',electronics:'ϟ',analysis:'⌁',cost:'▤',evidence:'◫',revisions:'↺',manufacturing:'⚒'};
const metric=(label,value,caption)=>`<div class="card metric"><label>${label}</label><strong>${value}</strong><small>${caption}</small></div>`;
function kinematics(stroke,rod,degrees,rpm){const r=stroke/2,t=degrees*Math.PI/180,s=Math.sin(t),c=Math.cos(t),root=Math.sqrt(rod*rod-r*r*s*s),w=rpm*2*Math.PI/60;return {valid:rod>r,x:r*(1-c)+rod-root,velocity:(r*s+r*r*s*c/root)*w/1000,angle:t,crankX:r*c,crankY:r*s,piston:r*c+root}};
function projectSignature(p){return JSON.stringify({stroke:p.stroke,rod:p.rod,rpm:p.rpm,material:p.material,parts:p.parts})}
function stale(n){return n.signature&&n.signature!==projectSignature(current)}
function costModel(){const c=current.costSettings||{quantity:1,labor:0,tooling:0,overhead:0};return {...c,unit:total()+c.labor,batch:(total()+c.labor)*c.quantity+c.tooling,all:((total()+c.labor)*c.quantity+c.tooling)*(1+c.overhead/100)}}
function mechanicalScene(){const valid=current.rod>current.stroke/2;if(!valid)return '<div class="empty">This linkage cannot complete a rotation.<p>Set connecting rod length greater than half the stroke.</p></div>';const r=current.stroke/2,l=current.rod,scale=410/(l+2*r),cx=120,cy=180,rr=r*scale;let k=kinematics(current.stroke,l,phase,current.rpm),px=cx+k.piston*scale,ax=cx+k.crankX*scale,ay=cy-k.crankY*scale;let wire=viewMode==='wire';return `<svg id="kinematicScene" viewBox="0 0 700 340" role="img" aria-label="Parametric slider-crank mechanism at ${phase.toFixed(0)} degrees"><defs><linearGradient id="copper" x2="0" y2="1"><stop stop-color="#e3b27f"/><stop offset="1" stop-color="#ad744d"/></linearGradient><linearGradient id="pistonMetal" x2="0" y2="1"><stop stop-color="#d3e0cc"/><stop offset=".5" stop-color="#f7fbf3"/><stop offset="1" stop-color="#9cb28d"/></linearGradient></defs><g stroke="#8ea386" stroke-width="1" opacity=".25"><path stroke-dasharray="5 6" d="M30 ${cy}H660"/><path d="M${cx} 50V290"/></g><path d="M65 260H630L660 278H45Z" fill="${wire?'none':'#c2cfb6'}" stroke="#8fa67e"/><path d="M65 260V278H630V260" fill="${wire?'none':'#a8ba99'}" stroke="#8fa67e"/><rect x="${cx-32}" y="${cy+rr+14}" width="64" height="${Math.max(4,65-rr)}" rx="5" fill="${wire?'none':'#819774'}" stroke="#658157"/><circle cx="${cx}" cy="${cy}" r="${rr+13}" fill="${wire?'none':'#d8e2ce'}" stroke="#94aa83" stroke-width="2"/><circle cx="${cx}" cy="${cy}" r="${rr}" fill="none" stroke="#a1b491" stroke-dasharray="4 4"/><line x1="${cx}" y1="${cy}" x2="${ax}" y2="${ay}" stroke="${wire?'#749565':'url(#copper)'}" stroke-width="${wire?3:19}" stroke-linecap="round"/><path d="M${cx+l*scale-rr-25} ${cy-38}H${cx+l*scale+rr+65}V${cy+38}H${cx+l*scale-rr-25}" fill="${wire?'none':'#e4ebde88'}" stroke="#9eae92" stroke-width="2"/><rect x="${px-27}" y="${cy-29}" width="64" height="58" rx="6" fill="${wire?'none':'url(#pistonMetal)'}" stroke="#8fa580" stroke-width="2"/><line x1="${ax}" y1="${ay}" x2="${px}" y2="${cy}" stroke="${wire?'#69875a':'#96ad83'}" stroke-width="${wire?3:14}" stroke-linecap="round"/><line x1="${ax}" y1="${ay-2}" x2="${px}" y2="${cy-2}" stroke="#d5e3ca" stroke-width="${wire?0:3}"/><g fill="#eaf0e3" stroke="#628152" stroke-width="3"><circle cx="${cx}" cy="${cy}" r="7"/><circle cx="${ax}" cy="${ay}" r="7"/><circle cx="${px}" cy="${cy}" r="7"/></g><g font-family="monospace" font-size="10" fill="#749066"><path d="M${cx} 302H${cx+rr}" stroke="#829a74"/><path d="M${cx} 296V308M${cx+rr} 296V308" stroke="#829a74"/><text x="${cx}" y="325">r = ${r} mm</text><text x="${(ax+px)/2-20}" y="${Math.min(ay,cy)-28}">L = ${l} mm</text><text x="510" y="45">θ ${phase.toFixed(0)}°</text><text x="510" y="65">x ${k.x.toFixed(2)} mm</text></g></svg>`}
function chart(){if(current.rod<=current.stroke/2)return '<div class="empty">Resolve geometry to generate a displacement curve.</div>';let pts=[];for(let a=0;a<=360;a+=3)pts.push(`${45+a/360*610},${175-kinematics(current.stroke,current.rod,a,current.rpm).x/current.stroke*140}`);return `<svg class="plot" viewBox="0 0 700 215" role="img" aria-label="Piston displacement over a full crank rotation"><defs><linearGradient id="plotFill" x2="0" y2="1"><stop stop-color="#83a86d" stop-opacity=".25"/><stop offset="1" stop-color="#83a86d" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<path d="M45 ${175-v*140}H655" stroke="#e4e9df" stroke-dasharray="3 5"/><text x="5" y="${179-v*140}" fill="#8b9781" font-size="10">${(v*current.stroke).toFixed(0)}</text>`).join('')}<path d="M45 175L${pts.join('L')}L655 175Z" fill="url(#plotFill)"/><polyline points="${pts.join(' ')}" fill="none" stroke="#5d8750" stroke-width="2.5"/>${[0,90,180,270,360].map(a=>`<text x="${39+a/360*610}" y="200" fill="#8b9781" font-size="10">${a}°</text>`).join('')}<line x1="${45+phase/360*610}" x2="${45+phase/360*610}" y1="25" y2="178" stroke="#b8895e" stroke-dasharray="4 4"/></svg>`}
function designV2(){return `<div class="workspaceBanner"><div><span class="liveDot"></span> CONNECTED DESIGN <span class="bannerDivider">/</span> ${esc(current.kind)}</div><span>Concept → Evaluate → Document</span></div><div class="designGrid advancedGrid"><section class="card canvasCard"><div class="canvasToolbar"><div class="segmented"><button data-mode="solid" class="${viewMode==='solid'?'selected':''}">Solid</button><button data-mode="wire" class="${viewMode==='wire'?'selected':''}">Wireframe</button></div><span class="tiny">PARAMETRIC · 2D KINEMATICS</span><button id="downloadGeometry" title="Export current mechanism as SVG">↓ SVG</button></div><div class="liveViewport"><div class="viewLabel">SLIDER-CRANK ASSEMBLY<span>Dimensions drive this mechanism</span></div><span class="canvasBadge">XY / ORTHOGRAPHIC</span><div id="scene">${mechanicalScene()}</div><div class="viewportCaption">${current.rod>current.stroke/2?'● Ideal geometry consistent':'● Geometry needs attention'}<span>mm</span></div></div><div class="transport"><button id="playMotion" class="playButton" ${current.rod<=current.stroke/2?'disabled':''}>▶</button><div class="timeline"><div><label for="phase">CRANK ANGLE</label><strong id="angleValue">${phase.toFixed(0)}°</strong></div><input id="phase" type="range" min="0" max="360" value="${phase}" aria-label="Crank angle"></div><select id="playSpeed" aria-label="Playback speed"><option value=".25">0.25×</option><option value=".5" selected>0.5×</option><option value="1">1×</option></select><span class="tiny">Visual playback<br>independent of RPM</span></div><div class="canvasFooter"><span>↔ Scrub to inspect linkage positions</span><button id="resetMotion">Reset view</button></div></section><section class="card inspector"><div class="cardHead"><h2>Parameter inspector</h2><span class="pill">EDITABLE</span></div><div class="properties"><div class="inspectorSection">01 / GEOMETRY</div>${field('stroke','Stroke · mm',current.stroke,'number')}${field('rod','Rod length · mm',current.rod,'number')}<div class="inspectorSection">02 / OPERATING POINT</div>${field('rpm','Speed · RPM',current.rpm,'number')}<div class="field"><label for="material">Primary material</label><select id="material">${['Aluminium 6061','Steel','ABS polymer'].map(m=>`<option ${m===current.material?'selected':''}>${m}</option>`).join('')}</select></div><button class="primary" id="apply" style="width:100%">Update design ↗</button></div><div class="dependencyNote"><span>↳</span><div><b>Connected dependencies</b><small>Motion curve · geometry check · saved calculation evidence</small></div></div></section></div><div class="metrics">${metric('CRANK RADIUS',current.stroke/2+'<em> mm</em>','Half of the specified stroke')}${metric('ROD / CRANK RATIO',(current.rod/(current.stroke/2)).toFixed(2)+'<em> : 1</em>','Ideal full rotation requires > 1')}${metric('MEAN PISTON SPEED',(2*current.stroke/1000*current.rpm/60).toFixed(2)+'<em> m/s</em>','Ideal kinematic calculation')}${metric('COMPONENT ESTIMATE',money(total()),'Planning prices · excludes fabrication')}</div><div class="lower curveRow"><section class="card"><div class="cardHead"><h2>Motion study</h2><span class="tiny">DISPLACEMENT / mm</span></div><div id="curve">${chart()}</div><div class="chartFoot"><span><i></i> Piston displacement</span><button data-tab="analysis">Open analysis ↗</button></div></section><section class="card assistant"><div class="cardHead"><h2>✧ Engineering guide</h2><span class="tiny">LOCAL GUIDANCE</span></div><div class="assistantBody"><div class="guideAvatar">✧</div><p id="answer">Your design is connected. Ask about the mechanism, inspect dimensions, or review the cost assumptions before your next iteration.</p><form id="guide"><div class="promptrow"><input id="question" aria-label="Ask engineering guide" placeholder="Explore your design…" required><button class="primary" aria-label="Send question">↗</button></div></form><div class="suggestions"><button data-question="Explain mechanism">Explain mechanism</button><button data-question="Check dimensions">Check dimensions</button><button data-question="Review cost">Review cost</button></div><small class="tiny">Deterministic guidance · live AI integration pending</small></div></section></div>`}
function sketchMarkup(){return (current.sketch||[]).map((s,i)=>s.type==='rect'?`<rect x="${s.x}" y="${s.y}" width="${s.w}" height="${s.h}" rx="1" fill="#64885022" stroke="#648850" stroke-width="2"/>`:s.type==='circle'?`<circle cx="${s.x}" cy="${s.y}" r="${s.r}" fill="#bc8d6022" stroke="#b58455" stroke-width="2"/>`:`<line x1="${s.x}" y1="${s.y}" x2="${s.x2}" y2="${s.y2}" stroke="#648850" stroke-width="2"/>`).join('')}
function sketchV2(){return `<div class="sectionLead"><div><span class="eyebrow">THINK IN SHAPES</span><h2>Sketch your starting point.</h2><p>Draw a concept in millimeters. Export an editable SVG to continue elsewhere.</p></div><span class="tag">Concept sketch · no constraint solver</span></div><section class="card"><div class="canvasToolbar"><div class="segmented">${[['rect','▭ Rectangle'],['circle','○ Circle'],['line','╱ Line']].map(([t,n])=>`<button data-tool="${t}" class="${sketchTool===t?'selected':''}">${n}</button>`).join('')}</div><div><button id="undoShape">↶ Undo shape</button> <button id="exportSketch">↓ Export SVG</button></div></div><svg id="sketchCanvas" viewBox="0 0 800 440" role="img" aria-label="Concept sketch canvas, click and drag to draw"><defs><pattern id="sketchGrid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" stroke="#cdd8c5" stroke-width=".6" fill="none"/></pattern></defs><rect width="800" height="440" fill="#f6f8f1"/><rect width="800" height="440" fill="url(#sketchGrid)"/><g id="shapes">${sketchMarkup()}</g><g id="draftShape" opacity=".5"></g></svg><div class="canvasFooter"><span id="sketchStatus">${(current.sketch||[]).length} shapes · grid 20 mm · drag to draw</span><span>800 × 440 mm</span></div></section>`}
function electronicsV2(){const e=current.circuit||{voltage:12,resistance:1000,rating:.25};return `<div class="sectionLead"><div><span class="eyebrow">ELECTRONICS & CONTROL</span><h2>Connect power to your idea.</h2><p>Inspect a resistive circuit and document the electrical specification.</p></div><span class="tag">Ideal DC resistor model</span></div><div class="lower" style="margin-top:0"><section class="card"><div class="cardHead"><h2>DC circuit calculator</h2><span class="pill">OHM’S LAW</span></div><div class="circuitDiagram"><svg viewBox="0 0 500 190" role="img" aria-label="Voltage source connected to a resistor"><path d="M100 90V40H230M270 40H400V155H100V120" fill="none" stroke="#78966a" stroke-width="2"/><circle cx="100" cy="105" r="26" fill="#edf3e6" stroke="#78966a" stroke-width="2"/><text x="92" y="104" fill="#557549">+</text><text x="94" y="119" fill="#557549">−</text><path d="M230 40l5 -12 6 24 6 -24 6 24 6 -24 6 24 5 -12" stroke="#b18a5f" fill="none" stroke-width="2"/><text x="238" y="78" fill="#839079" font-size="11">R</text><text x="52" y="110" fill="#839079" font-size="11">V</text><path d="M170 22h30l-6 -4m6 4l-6 4" fill="none" stroke="#78966a"/><text x="177" y="15" fill="#839079" font-size="10">I</text></svg></div><div class="properties"><div class="row">${field('voltage','Supply · V',e.voltage,'number')}${field('resistance','Resistance · Ω',e.resistance,'number')}${field('rating','Resistor rating · W',e.rating,'number')}</div><button id="calculateCircuit" class="primary">Calculate circuit</button><div id="circuitResults"></div></div></section><section class="card"><div class="cardHead"><h2>Electrical specification</h2><span class="tiny">PROJECT NOTES</span></div><div class="properties"><p class="tiny">Record drivers, connectors, firmware, wiring and power requirements.</p><div class="field"><label for="electrical">Specification</label><textarea id="electrical" style="min-height:220px" placeholder="Supply voltage, motor driver, pin assignments…">${esc(current.electrical||'')}</textarea></div><button id="saveElectrical" class="primary">Save specification</button></div></section></div>`}
function compareV2(){const latest=current.revisions.at(-1);return `<div class="sectionLead"><div><span class="eyebrow">TRACE EVERY DECISION</span><h2>Revisions & comparison</h2><p>Compare the current design against a recoverable snapshot.</p></div><button class="primary" id="saveRevision2">＋ Save revision</button></div>${current.revisions.length?`<section class="card pageCard"><div class="actions"><h2>What changed?</h2><select id="compareRevision" aria-label="Compare revision">${current.revisions.map((r,i)=>`<option value="${i}" ${r===latest?'selected':''}>R${i+1} · ${esc(r.label)}</option>`).join('')}</select></div><div id="comparison"></div></section><div style="height:20px"></div>`:''}${card('Revision timeline',current.revisions.length?[...current.revisions].reverse().map((r,i)=>`<div class="revision"><div><span class="pill">R${current.revisions.length-i}</span><h3 style="margin-top:10px">${esc(r.label)}</h3><p>${esc(r.date)} · ${r.snapshot.parts.length} component types</p></div><button data-restore="${current.revisions.length-1-i}">Restore snapshot</button></div>`).join(''):'<div class="empty">Your first iteration is worth saving.<p>Capture parameters, components, notes and sketches with Save revision.</p></div>')}`}
const taskDefaults=['Specify dimensions and tolerances','Select material and manufacturing process','Obtain supplier quotations','Review assembly clearances','Define test procedure and acceptance criteria'];
function manufacturingV2(){const tasks=current.buildTasks||taskDefaults.map(name=>({name,done:false}));let done=tasks.filter(t=>t.done).length,c=costModel();return `<div class="sectionLead"><div><span class="eyebrow">DESIGN → BUILD</span><h2>Make the next steps concrete.</h2><p>Plan fabrication, estimate a batch, and define what needs review.</p></div><button id="downloadReport">↓ Project report · HTML</button></div><div class="lower" style="margin-top:0"><section class="card"><div class="cardHead"><h2>Fabrication checklist</h2><span class="pill">${done} / ${tasks.length} COMPLETE</span></div><div class="properties"><div class="progress"><span style="width:${tasks.length?done/tasks.length*100:0}%"></span></div>${tasks.map((t,i)=>`<label class="taskRow"><input type="checkbox" data-task="${i}" ${t.done?'checked':''}><span>${esc(t.name)}</span></label>`).join('')}<button id="addTask" style="margin-top:18px">＋ Add task</button></div><div class="propertyFoot">Checklist completion does not certify fabrication readiness.</div></section><section class="card"><div class="cardHead"><h2>Batch cost planner</h2><span class="tiny">INR · ASSUMPTIONS</span></div><div class="properties"><div class="row">${field('batchQuantity','Production quantity',c.quantity,'number')}${field('labor','Labor / unit · INR',c.labor,'number')}</div><div class="row">${field('tooling','One-time tooling · INR',c.tooling,'number')}${field('overhead','Overhead · %',c.overhead,'number')}</div><button class="primary" id="updateBatch">Update estimate</button><div class="batchTotal"><span>BATCH PLANNING TOTAL</span><strong>${money(c.all)}</strong><small>${money(c.all/c.quantity)} / unit · ${c.quantity} units</small></div><p class="tiny">Uses current BOM prices. Tax, delivery, scrap and inspection excluded unless included in your assumptions. Not a supplier quotation.</p></div></section></div>`}
function compare(index){const p=current.revisions[index].snapshot;const values=[['Stroke',p.stroke,current.stroke,'mm'],['Rod length',p.rod,current.rod,'mm'],['Speed',p.rpm,current.rpm,'RPM'],['Material',p.material,current.material,''],['Unique components',p.parts.length,current.parts.length,''],['Component estimate',p.parts.reduce((s,a)=>s+a.qty*a.price,0),total(),'INR']];$('#comparison').innerHTML=`<div class="tableWrap"><table><thead><tr><th>PROPERTY</th><th>SAVED REVISION</th><th>CURRENT DESIGN</th><th>CHANGE</th></tr></thead><tbody>${values.map(([n,a,b,u])=>`<tr><td>${n}</td><td>${esc(a)} ${u}</td><td>${esc(b)} ${u}</td><td><span class="${a===b?'tiny':'pill'}">${a===b?'Unchanged':typeof a==='number'?(b-a>0?'+':'')+(b-a).toFixed(2)+' '+u:'Modified'}</span></td></tr>`).join('')}</tbody></table></div>`}
function circuitResult(){const e=current.circuit||{voltage:12,resistance:1000,rating:.25},i=e.voltage/e.resistance,p=e.voltage*i;$('#circuitResults').innerHTML=`<div class="miniMetrics"><div><label>CURRENT</label><strong>${(i*1000).toFixed(2)} mA</strong></div><div><label>POWER</label><strong>${p.toFixed(3)} W</strong></div></div><div class="note">${p<=e.rating?'Within':'Exceeds'} entered resistor power rating (${e.rating} W). Ideal DC model; temperature, tolerances, transients and derating are not modeled.</div>`}
function validProject(p){return p&&typeof p.name==='string'&&p.name.length<=200&&['stroke','rod','rpm'].every(k=>Number.isFinite(p[k])&&p[k]>0)&&typeof p.material==='string'&&Array.isArray(p.parts)&&p.parts.length<=10000&&p.parts.every(a=>a&&typeof a.name==='string'&&typeof a.material==='string'&&Number.isInteger(a.qty)&&a.qty>0&&Number.isFinite(a.price)&&a.price>=0)&&Array.isArray(p.notes)&&p.notes.every(n=>n&&['title','body','type','date'].every(k=>typeof n[k]==='string'))&&Array.isArray(p.revisions)&&p.revisions.every(r=>r&&typeof r.label==='string'&&typeof r.date==='string'&&validProject({...r.snapshot,revisions:[]}))&&(!p.sketch||Array.isArray(p.sketch)&&p.sketch.every(s=>['rect','circle','line'].includes(s.type)&&Object.entries(s).every(([k,v])=>k==='type'||Number.isFinite(v))))}
const baseProjectValidation=validProject; validProject=function(p){if(!baseProjectValidation(p))return false;if(p.kind!==undefined&&typeof p.kind!=="string")return false;if(p.electrical!==undefined&&typeof p.electrical!=="string")return false;if(p.costSettings&&(!Number.isInteger(p.costSettings.quantity)||p.costSettings.quantity<1||["labor","tooling","overhead"].some(k=>!Number.isFinite(p.costSettings[k])||p.costSettings[k]<0)))return false;if(p.circuit&&["voltage","resistance","rating"].some(k=>!Number.isFinite(p.circuit[k])||p.circuit[k]<=0))return false;if(p.buildTasks&&(!Array.isArray(p.buildTasks)||p.buildTasks.some(t=>!t||typeof t.name!=="string"||typeof t.done!=="boolean")))return false;return true}; function importProject(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;const limit=typeof studioBackend!=='undefined'&&studioBackend.enabled?1000000:5000000;if(file.size>limit)throw Error('Choose a project smaller than '+(limit/1000000)+' MB.');const p=StudioProjectData.parse(await file.text());if(!StudioProjectData.validate(p))throw Error('This is not a valid Engineering Studio project export.');p.name=p.name.slice(0,180)+' (imported)';await saveNewStudioProject(p);location.hash='/workspace?tool=design';showProductRoute();toast('Project imported as a new copy')}catch(e){toast(e.message)}};input.click()}
function report(){let c=costModel();download(current.name+'-report.html',`<!doctype html><html lang="en"><meta charset="utf-8"><title>${esc(current.name)} · Project report</title><style>body{font:14px system-ui;max-width:900px;margin:55px auto;color:#263528;padding:20px}h1{font-size:32px}h2{margin-top:36px}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}p{line-height:1.7}.note{background:#f1f4ec;padding:20px}</style><h1>${esc(current.name)}</h1><p>Engineering concept · ${esc(new Date().toLocaleString())}</p><div class="note">Planning and documentation record. No claim of reviewed design, fabrication readiness or physical validation.</div><h2>Design parameters · ${esc(current.designType||'slider-crank')}</h2><p>Stroke: ${current.stroke} mm · Rod: ${current.rod} mm · Speed: ${current.rpm} RPM · Material: ${esc(current.material)}</p><h2>Component planning estimate</h2><table><tr><th>Component</th><th>Material</th><th>Qty</th><th>Subtotal ${esc(current.currency||'INR')}</th></tr>${current.parts.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.material)}</td><td>${p.qty}</td><td>${p.qty*p.price}</td></tr>`).join('')}</table><p>Component total: ${money(total())}. Batch planning total: ${money(c.all)} for ${c.quantity} units. Manually entered assumptions; tax and shipping excluded.</p><h2>Electrical specification</h2><p style="white-space:pre-wrap">${esc(current.electrical||'Not specified')}</p><h2>Evidence</h2>${current.notes.map(n=>`<h3>${esc(n.title)} ${stale(n)?'· OUTDATED':''}</h3><p>${esc(n.type)} · ${esc(n.date)}</p><p style="white-space:pre-wrap">${esc(n.body)}</p>`).join('')||'<p>No evidence recorded.</p>'}<h2>Build checklist</h2>${(current.buildTasks||[]).map(t=>`<p>${t.done?'✓':'○'} ${esc(t.name)}</p>`).join('')}`,'text/html')}
render=function(){cancelAnimationFrame(raf);playback=false;baseRender();$('.beta').innerHTML='STUDIO PREVIEW <span>v15.2</span>';$('#subtitle').textContent='Design with intent. Explore the details. Keep every decision connected.';$('#tabs').innerHTML=page==='projects'?'':tabs.map(([id,n])=>`<button class="tab ${page===id?'active':''}" data-tab="${id}"><span>${icon[id]||'◇'}</span>${n}</button>`).join('');if(page==='design')$('#content').innerHTML=designV2();if(page==='sketch')$('#content').innerHTML=sketchV2();if(page==='electronics')$('#content').innerHTML=electronicsV2();if(page==='revisions')$('#content').innerHTML=compareV2();if(page==='manufacturing')$('#content').innerHTML=manufacturingV2();bind();bindAdvanced();if(page==='evidence'){document.querySelectorAll('.check').forEach((el,i)=>{if(stale(current.notes[i]))el.insertAdjacentHTML('afterbegin','<span class="outdated">OUTDATED · design parameters changed</span>')})}if(page==='analysis'){$('#content .card').insertAdjacentHTML('beforeend',`<div class="check"><h3>Full-cycle displacement</h3>${chart()}<button id="exportMotion">↓ Export motion samples · CSV</button></div>`);$('#exportMotion').onclick=()=>{if(current.rod<=current.stroke/2){toast('Resolve geometry before exporting motion');return}download('motion-study.csv','Angle degrees,Displacement mm,Velocity m per s\r\n'+Array.from({length:361},(_,a)=>{let k=kinematics(current.stroke,current.rod,a,current.rpm);return [a,k.x.toFixed(5),k.velocity.toFixed(5)].join(',')}).join('\r\n'),'text/csv')};$('#recordCheck').onclick=()=>{current.notes.push({title:'Ideal kinematic calculation',type:'Calculated · not physically validated',date:new Date().toLocaleString(),signature:projectSignature(current),body:`Stroke ${current.stroke} mm; rod ${current.rod} mm; speed ${current.rpm} RPM. Mean piston speed ${(2*current.stroke/1000*current.rpm/60).toFixed(2)} m/s. Rod > crank radius: ${current.rod>current.stroke/2}. Ideal rigid linkage. No friction or load model.`});persist();toast('Calculation recorded with design dependency tracking')}}if(page==='projects'){$('.actions').insertAdjacentHTML('afterbegin','<button id="importInProjects">↑ Import project</button>');$('#importInProjects').onclick=importProject}};
function updateScene(){if(!$('#scene'))return;$('#scene').innerHTML=mechanicalScene();$('#angleValue').textContent=phase.toFixed(0)+'°';$('#phase').value=phase;$('#curve').innerHTML=chart()}
function animateMotion(time){if(!playback||page!=='design')return;if(lastFrame)phase=(phase+Math.min(time-lastFrame,50)*.09*+$('#playSpeed').value)%360;lastFrame=time;updateScene();raf=requestAnimationFrame(animateMotion)}
function bindAdvanced(){document.querySelectorAll("[data-restore]").forEach(b=>b.onclick=()=>{const snapshot=structuredClone(current.revisions[+b.dataset.restore].snapshot),revisions=current.revisions,id=current.id;Object.keys(current).forEach(k=>delete current[k]);Object.assign(current,JSON.parse(JSON.stringify(snapshot),(k,v)=>["__proto__","constructor","prototype"].includes(k)?undefined:v),{id,revisions});persist();render();toast("Complete revision restored")});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{viewMode=b.dataset.mode;render()});if($('#phase'))$('#phase').oninput=e=>{phase=+e.target.value;updateScene()};if($('#playMotion'))$('#playMotion').onclick=()=>{playback=!playback;$('#playMotion').textContent=playback?'Ⅱ':'▶';lastFrame=0;if(playback)raf=requestAnimationFrame(animateMotion);else cancelAnimationFrame(raf)};if($('#resetMotion'))$('#resetMotion').onclick=()=>{phase=45;playback=false;cancelAnimationFrame(raf);$('#playMotion').textContent='▶';updateScene()};if($('#downloadGeometry'))$('#downloadGeometry').onclick=()=>{const svg=$('#kinematicScene');if(!svg){toast('Resolve geometry before export');return}download('mechanism-concept.svg',svg.outerHTML.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" '),'image/svg+xml')};if($('#saveRevision2'))$('#saveRevision2').onclick=()=>$('#saveRevision').click();if($('#compareRevision')){$('#compareRevision').onchange=e=>compare(+e.target.value);compare(+$('#compareRevision').value)}if($('#calculateCircuit')){$('#calculateCircuit').onclick=()=>{let e={voltage:+$('#voltage').value,resistance:+$('#resistance').value,rating:+$('#rating').value};if(Object.values(e).some(v=>!Number.isFinite(v)||v<=0)){toast('Use positive electrical values');return}current.circuit=e;persist();circuitResult()};['voltage','resistance','rating'].forEach(k=>{$('#'+k).min='.000001';$('#'+k).step='any'});circuitResult()}if($('#updateBatch')){['labor','tooling','overhead'].forEach(k=>{$('#'+k).min=0;$('#'+k).step='any'});$('#updateBatch').onclick=()=>{let c={quantity:+$('#batchQuantity').value,labor:+$('#labor').value,tooling:+$('#tooling').value,overhead:+$('#overhead').value};if(!Number.isInteger(c.quantity)||c.quantity<1||Object.values(c).some(v=>!Number.isFinite(v)||v<0)){toast('Use a positive whole quantity and nonnegative costs');return}current.costSettings=c;persist();render();toast('Batch planning estimate updated')}}document.querySelectorAll('[data-task]').forEach(b=>b.onchange=()=>{current.buildTasks||=taskDefaults.map(name=>({name,done:false}));current.buildTasks[+b.dataset.task].done=b.checked;persist();render()});if($('#addTask'))$('#addTask').onclick=()=>modal('Add build task',field('name','Task description',''),f=>{if(!f.get('name').trim())return;current.buildTasks||=taskDefaults.map(name=>({name,done:false}));current.buildTasks.push({name:f.get('name'),done:false});persist();render()});if($('#downloadReport'))$('#downloadReport').onclick=report;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{sketchTool=b.dataset.tool;render()});if($('#sketchCanvas')){const canvas=$('#sketchCanvas');const point=e=>{const matrix=canvas.getScreenCTM();const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());return {x:Math.round(Math.max(0,Math.min(800,p.x))/5)*5,y:Math.round(Math.max(0,Math.min(440,p.y))/5)*5}};const shape=(a,b)=>sketchTool==='rect'?{type:'rect',x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(a.x-b.x),h:Math.abs(a.y-b.y)}:sketchTool==='circle'?{type:'circle',x:a.x,y:a.y,r:Math.hypot(b.x-a.x,b.y-a.y)}:{type:'line',x:a.x,y:a.y,x2:b.x,y2:b.y};canvas.onpointerdown=e=>{sketchStart=point(e);canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{let p=point(e);$('#sketchStatus').textContent=`X ${p.x} · Y ${p.y} mm · snap 5 mm`;if(sketchStart){let a=current.sketch;current.sketch=[shape(sketchStart,p)];$('#draftShape').innerHTML=sketchMarkup();current.sketch=a}};canvas.onpointerup=e=>{if(!sketchStart)return;let p=point(e);if(Math.hypot(p.x-sketchStart.x,p.y-sketchStart.y)>3){current.sketch||=[];current.sketch.push(shape(sketchStart,p));persist()}sketchStart=null;$('#shapes').innerHTML=sketchMarkup();$('#draftShape').innerHTML='';$('#sketchStatus').textContent=`${(current.sketch||[]).length} shapes · grid 20 mm · drag to draw`};canvas.onpointercancel=()=>{sketchStart=null;$('#draftShape').innerHTML=''};$('#undoShape').onclick=()=>{current.sketch?.pop();persist();render()};$('#exportSketch').onclick=()=>download('concept-sketch.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="800mm" height="440mm" viewBox="0 0 800 440">${sketchMarkup()}</svg>`,'image/svg+xml')}}
document.querySelectorAll(".nav").forEach(b=>b.setAttribute("aria-label",b.textContent.trim())); const quickActions=[['Create new project',()=>newProject()],['Import project JSON',importProject],['Export project JSON',()=>$('#export').click()],['Save revision',()=>$('#saveRevision').click()],...tabs.map(([id,label])=>['Open '+label,()=>navigate(id)])];
function commandPalette(){modal('Quick actions','<div class="field"><label for="commandSearch">Find an action</label><input id="commandSearch" placeholder="Search pages and actions…" autocomplete="off"></div><div id="commandList"></div>',()=>{});$('#modalForm>button[type=submit]').style.display='none';const list=q=>{$('#commandList').innerHTML=quickActions.map(([n],i)=>({n,i})).filter(a=>a.n.toLowerCase().includes(q.toLowerCase())).map(a=>`<button type="button" class="commandItem" data-command="${a.i}">${a.n}<span>↗</span></button>`).join('')||'<p>No matching actions.</p>';document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{$('#dialog').close();$('#modalForm>button[type=submit]').style.display='';quickActions[+b.dataset.command][1]()})};list('');$('#commandSearch').oninput=e=>list(e.target.value);$('#commandSearch').focus()}
const baseModal=modal;modal=function(...args){$('#modalForm>button[type=submit]').style.display='';baseModal(...args)};
$('.headerActions').insertAdjacentHTML('afterbegin','<button id="quickActions" class="quickSearch" title="Quick actions (Ctrl+K)">⌕ <span>Quick actions</span><kbd>Ctrl K</kbd></button><button id="importProject" title="Import exported project JSON">↑ Import</button>');$('#quickActions').onclick=commandPalette;$('#importProject').onclick=importProject;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();commandPalette()}});$('#newProject').textContent='＋ New project';render();
